pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();
    let total_residuum = node_residual_cpu + node_residual_ram;

    // Calculate post-job residuals
    let post_cpu_residuum = if job_cpu <= node_residual_cpu { node_residual_cpu - job_cpu } else { 0 };
    let post_ram_residuum = if job_ram <= node_residual_ram { node_residual_ram - job_ram } else { 0 };

    // Lookahead penalty for next job
    let lookahead_penalty = if post_cpu_residuum >= next_job_cpu && post_ram_residuum >= next_job_ram {
        0.0
    } else {
        (next_job_cpu as f64 + next_job_ram as f64) / 2.0 * 1.5 // Increased penalty for lookahead mismatch
    };

    // Dynamic horizon awareness factor
    let dynamic_horizon_factor = step_index as f64 / total_jobs as f64;

    // Non-linear conditionals and packing bonuses
    let cpu_packing_bonus = if node_residual_cpu <= mean_cpu_residual { -10.0 } else { 0.0 };
    let ram_packing_bonus = if node_residual_ram <= mean_ram_residual { -10.0 } else { 0.0 };

    // Encourage balanced usage of CPU and RAM
    let balance_bonus = (node_capacity_cpu as f64 * cpu_norm + node_capacity_ram as f64 * ram_norm) / (node_capacity_cpu as f64 + node_capacity_ram as f64);

    // Calculate score
    let mut score = total_residuum as f64;
    score -= imbalance_penalty * 150.0; // Penalize resource imbalance heavily
    score += lookahead_penalty * 75.0;   // Reward fitting next job well
    score -= dynamic_horizon_factor * 25.0; // Penalize jobs later in the schedule
    score += cpu_packing_bonus + ram_packing_bonus; // Encourage packing of resources
    score += balance_bonus * 50.0; // Encourage balanced resource usage

    score
}

pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = (node_residual_cpu as f64 - job_cpu as f64) / node_capacity_cpu as f64;
    let ram_norm = (node_residual_ram as f64 - job_ram as f64) / node_capacity_ram as f64;
    let imbalance = (cpu_norm - ram_norm).abs();

    // Introduce lookahead packing bonuses
    let lookahead_bonus = if next_job_cpu > 0 && next_job_ram > 0 {
        1.0 + (next_job_cpu as f64 / node_capacity_cpu as f64) * (next_job_ram as f64 / node_capacity_ram as f64)
    } else {
        1.0
    };

    // Introduce imbalance penalties
    let imbalance_penalty = if imbalance > 0.5 {
        imbalance * 2.0
    } else {
        imbalance * 1.0
    };

    // Fine-grained residual fitting
    let cpu_resid_fit = (node_residual_cpu as f64 / node_capacity_cpu as f64).powi(2);
    let ram_resid_fit = (node_residual_ram as f64 / node_capacity_ram as f64).powi(2);

    // Horizon-aware placement logic
    let horizon_factor = (step_index as f64 / total_jobs as f64).powi(2);

    let score = cpu_norm + ram_norm + imbalance * 5.0 + lookahead_bonus * 3.0 - imbalance_penalty * 1.5 + cpu_resid_fit * 0.8 + ram_resid_fit * 0.8 + horizon_factor * 0.5;
    score
}

