    let ram_norm = (node_residual_ram as f64 - job_ram as f64) / node_capacity_ram as f64;
    let imbalance = (cpu_norm - ram_norm).abs();
    let lookahead_penalty = if next_job_cpu == 0 && next_job_ram == 0 {
        0.0
    } else {
        let next_cpu_norm = (node_residual_cpu as f64 - next_job_cpu as f64) / node_capacity_cpu as f64;
        let next_ram_norm = (node_residual_ram as f64 - next_job_ram as f64) / node_capacity_ram as f64;
